mapper.select:
SELECT ROLE_TP
	  ,MENU_ID
  FROM TB_SYME002
 WHERE ROLE_TP = #{roleAuthority.roleType, typeHandler=UserRoleTypeHandler}
   AND MENU_ID = #{roleAuthority.menuId}

SELECT COUNT(MN.MENU_ID)
  FROM TB_SYME001 MN
       INNER JOIN TB_SYME002 RO
    ON MN.MENU_ID = RO.MENU_ID
 WHERE RO.ROLE_TP = #{roleAuthority.roleType, typeHandler=UserRoleTypeHandler}
   AND MN.HI_MNU_ID = #{roleAuthority.menuId};

mapper.insert:
INSERT INTO TB_SYME002 (
	 ROLE_TP
	,MENU_ID
) VALUES (
	 #{roleAuthority.roleType, typeHandler=UserRoleTypeHandler}
	,#{roleAuthority.menuId}
)

mapper.update:
UPDATE TB_SYME002
   SET MENU_ID =  #{roleAuthority.menuId}
 WHERE ROLE_TP = #{roleAuthority.roleType, typeHandler=UserRoleTypeHandler}

mapper.delete:
DELETE FROM TB_SYME002
WHERE ROLE_TP = #{roleAuthority.roleType, typeHandler=UserRoleTypeHandler}
AND MENU_ID = #{roleAuthority.menuId}
